async function apiGet(endpoint) {
  if (window.location.protocol !== "file:") {
    try {
      const headers = {};
      if (typeof state !== "undefined" && state.staffToken) {
        headers["Authorization"] = "Bearer " + state.staffToken;
      }
      const res = await fetch("/api/" + endpoint, { headers });
      if (res.ok) return await res.json();
    } catch (e) {}
  }
  return handleLocalMock(endpoint, "GET");
}

async function apiPost(endpoint, data) {
  if (window.location.protocol !== "file:") {
    try {
      const headers = { "Content-Type": "application/json" };
      if (typeof state !== "undefined" && state.staffToken) {
        headers["Authorization"] = "Bearer " + state.staffToken;
      }
      const res = await fetch("/api/" + endpoint, {
        method: "POST",
        headers: headers,
        body: JSON.stringify(data)
      });
      if (res.ok) return await res.json();
    } catch (e) {}
  }
  return handleLocalMock(endpoint, "POST", data);
}

async function apiPut(endpoint, data) {
  if (window.location.protocol !== "file:") {
    try {
      const headers = { "Content-Type": "application/json" };
      if (typeof state !== "undefined" && state.staffToken) {
        headers["Authorization"] = "Bearer " + state.staffToken;
      }
      const res = await fetch("/api/" + endpoint, {
        method: "PUT",
        headers: headers,
        body: JSON.stringify(data)
      });
      if (res.ok) return await res.json();
    } catch (e) {}
  }
  return handleLocalMock(endpoint, "PUT", data);
}

