function switchAdminTab(tabName) {
  state.adminTab = tabName;

  // Sync mobile module dropdown if present
  const mobErpSel = document.getElementById("mobile-erp-module-select");
  if (mobErpSel && mobErpSel.value !== tabName) {
    mobErpSel.value = tabName;
  }

  const tabs = ["overview", "inquiries_orders", "purchase_shortage", "accounts_ledger", "jobsheets", "inventory", "serials", "billing", "staff", "warehouses", "amc", "referrals", "backup_restore"];
  tabs.forEach(t => {
    const panel = document.getElementById("admin-tab-" + t);
    const btn = document.getElementById("tab-btn-" + t);
    if (panel) {
      if (t === tabName) {
        panel.classList.remove("hidden");
        panel.classList.add("animate-fade-in");
      } else {
        panel.classList.add("hidden");
        panel.classList.remove("animate-fade-in");
      }
    }
    if (btn) {
      if (t === tabName) {
        btn.className = "admin-tab active shrink-0 whitespace-nowrap px-3.5 py-2 rounded-xl text-xs font-bold bg-gradient-to-r from-brand-600 to-indigo-600 text-white shadow-lg shadow-brand-500/25 transition-all duration-150 flex items-center gap-2 cursor-pointer active:scale-95";
      } else {
        btn.className = "admin-tab shrink-0 whitespace-nowrap px-3.5 py-2 rounded-xl text-xs font-bold bg-slate-800/90 text-slate-300 hover:bg-slate-700 hover:text-white border border-slate-700/60 transition-all duration-150 flex items-center gap-2 cursor-pointer active:scale-95 hover:-translate-y-0.5";
      }
    }
  });

  if (tabName === "overview") loadAdminStats();
  if (tabName === "inquiries_orders") loadInquiriesAndOrders();
  if (tabName === "purchase_shortage") loadPurchaseAndShortage();
  if (tabName === "accounts_ledger") loadAccountsAndLedger();
  if (tabName === "jobsheets") loadJobSheets();
  if (tabName === "inventory") loadInventoryTable();
  if (tabName === "serials") loadSerialsTable();
  if (tabName === "billing") loadInvoicesTable();
  if (tabName === "amc") loadAMCTable();
  if (tabName === "staff") renderStaffTab();
  if (tabName === "warehouses") loadWarehousesAndStocks();
  if (tabName === "referrals") loadAdminReferrals();
  if (tabName === "backup_restore") loadAdminBackups();
}

async function loadProducts() {
  const data = await apiGet("products");
  if (data && Array.isArray(data)) {
    state.products = data;
    populateSidebarBrands();
    applyCatalogFilters();
  } else {
    populateSidebarBrands();
    applyCatalogFilters();
  }
}

function escapeHtml(str) {
  if (!str) return "";
  return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

function populateSidebarBrands() {
  const container = document.getElementById("sidebar-brands-list");
  if (!container || !state.products) return;

  const brandCounts = {};
  state.products.forEach(p => {
    if (p.brand) {
      brandCounts[p.brand] = (brandCounts[p.brand] || 0) + 1;
    }
  });

  const sortedBrands = Object.keys(brandCounts).sort();
  container.innerHTML = sortedBrands.map(brand => {
    const isChecked = state.catalogFilters.brands.includes(brand) ? "checked" : "";
    return `
      <label class="flex items-center justify-between cursor-pointer hover:text-slate-900 select-none py-0.5">
        <div class="flex items-center gap-2">
          <input type="checkbox" value="${escapeHtml(brand)}" ${isChecked} onchange="handleBrandFilter(this)" class="brand-filter-cb rounded text-brand-600 focus:ring-brand-500 w-3.5 h-3.5 cursor-pointer">
          <span class="text-xs text-slate-700">${escapeHtml(brand)}</span>
        </div>
        <span class="text-[10px] text-slate-400 font-mono">(${brandCounts[brand]})</span>
      </label>
    `;
  }).join("");
}

function applyCatalogFilters() {
  const f = state.catalogFilters;
  
  let result = (state.products || []).filter(p => {
    // 1. Category
    if (f.category && f.category !== "all" && p.category !== f.category) {
      return false;
    }

    // 2. Search
    if (f.search) {
      const q = f.search.toLowerCase().trim();
      const inName = p.name ? p.name.toLowerCase().includes(q) : false;
      const inBrand = p.brand ? p.brand.toLowerCase().includes(q) : false;
      const inModel = p.model ? p.model.toLowerCase().includes(q) : false;
      const inSku = p.sku ? p.sku.toLowerCase().includes(q) : false;
      const inSpecs = p.specs ? p.specs.toLowerCase().includes(q) : false;
      if (!inName && !inBrand && !inModel && !inSku && !inSpecs) {
        return false;
      }
    }

    // 3. Brands
    if (f.brands && f.brands.length > 0) {
      if (!f.brands.includes(p.brand)) {
        return false;
      }
    }

    // 4. Price range
    if (f.priceRange && f.priceRange !== "all") {
      const price = p.selling_price;
      if (f.priceRange === "0-5000" && price > 5000) return false;
      if (f.priceRange === "5000-20000" && (price < 5000 || price > 20000)) return false;
      if (f.priceRange === "20000-50000" && (price < 20000 || price > 50000)) return false;
      if (f.priceRange === "50000-999999" && price < 50000) return false;
    }

    // 5. Min Rating
    if (f.minRating > 0) {
      const rating = parseFloat((4.3 + ((p.id * 7) % 7) / 10).toFixed(1));
      if (rating < f.minRating) return false;
    }

    // 6. In-Stock Only
    if (f.inStockOnly && p.stock_quantity <= 0) {
      return false;
    }

    // 7. Same-Day Delivery Rajkot
    if (f.sameDayOnly) {
      if (p.stock_quantity < 2) return false;
    }

    return true;
  });

  // Sorting
  if (f.sortBy === "price-asc") {
    result.sort((a, b) => a.selling_price - b.selling_price);
  } else if (f.sortBy === "price-desc") {
    result.sort((a, b) => b.selling_price - a.selling_price);
  } else if (f.sortBy === "rating") {
    result.sort((a, b) => {
      const rA = 4.3 + ((a.id * 7) % 7) / 10;
      const rB = 4.3 + ((b.id * 7) % 7) / 10;
      return rB - rA;
    });
  } else if (f.sortBy === "name") {
    result.sort((a, b) => a.name.localeCompare(b.name));
  } else {
    // Featured default
    result.sort((a, b) => {
      if (a.stock_quantity > 0 && b.stock_quantity <= 0) return -1;
      if (a.stock_quantity <= 0 && b.stock_quantity > 0) return 1;
      return a.id - b.id;
    });
  }

  state.filteredProducts = result;

  // Update count label
  const countLabel = document.getElementById("catalog-count-label");
  if (countLabel) {
    if (result.length === state.products.length) {
      countLabel.textContent = `Showing all ${result.length} hardware products`;
    } else {
      countLabel.textContent = `Showing ${result.length} of ${state.products.length} products`;
    }
  }

  renderProductsGrid();
}

function handleBrandFilter(cb) {
  if (cb.checked) {
    if (!state.catalogFilters.brands.includes(cb.value)) {
      state.catalogFilters.brands.push(cb.value);
    }
  } else {
    state.catalogFilters.brands = state.catalogFilters.brands.filter(b => b !== cb.value);
  }
  applyCatalogFilters();
}

function handlePriceFilter(range) {
  state.catalogFilters.priceRange = range;
  applyCatalogFilters();
}

function handleRatingFilter(minStars) {
  state.catalogFilters.minRating = minStars;
  applyCatalogFilters();
}

function handleInStockFilter(checked) {
  state.catalogFilters.inStockOnly = checked;
  applyCatalogFilters();
}

function handleSameDayFilter(checked) {
  state.catalogFilters.sameDayOnly = checked;
  applyCatalogFilters();
}

function handleCatalogSort(val) {
  state.catalogFilters.sortBy = val;
  applyCatalogFilters();
}

function handleAmazonSearch(e) {
  if (e) e.preventDefault();
  const searchInput = document.getElementById("header-search-input");
  const val = searchInput ? searchInput.value.trim() : "";
  state.catalogFilters.search = val;
  applyCatalogFilters();
  if (state.currentView !== "catalog") switchView("catalog");
  const catalogEl = document.getElementById("products-grid");
  if (catalogEl) {
    const topBar = document.getElementById("catalog-sort");
    if (topBar) topBar.scrollIntoView({ behavior: "smooth", block: "center" });
  }
}

function handleAmazonCatChange() {
  const catSelect = document.getElementById("header-search-cat");
  if (!catSelect) return;
  const val = catSelect.value;
  state.catalogFilters.category = val;

  document.querySelectorAll(".cat-pill").forEach(pill => {
    pill.classList.remove("bg-slate-900", "text-white", "shadow-xs");
    pill.classList.add("bg-slate-100", "text-slate-700");
  });

  applyCatalogFilters();
  if (state.currentView !== "catalog") switchView("catalog");
}

function filterCategory(cat, btn) {
  state.catalogFilters.category = cat;

  document.querySelectorAll(".cat-pill").forEach(pill => {
    pill.classList.remove("bg-slate-900", "text-white", "shadow-xs");
    pill.classList.add("bg-slate-100", "text-slate-700");
  });
  if (btn) {
    btn.classList.add("bg-slate-900", "text-white", "shadow-xs");
    btn.classList.remove("bg-slate-100", "text-slate-700");
  }

  const headerCat = document.getElementById("header-search-cat");
  if (headerCat) {
    headerCat.value = cat;
  }

  applyCatalogFilters();
  if (state.currentView !== "catalog") switchView("catalog");
}

let searchDebounceTimer = null;
function debounceProductSearch(val) {
  clearTimeout(searchDebounceTimer);
  searchDebounceTimer = setTimeout(() => {
    const searchVal = (val !== undefined ? val : (document.getElementById("header-search-input")?.value || "")).toLowerCase().trim();
    state.catalogFilters.search = searchVal;
    applyCatalogFilters();
  }, 200);
}

function resetAllFilters() {
  state.catalogFilters = {
    category: "all",
    search: "",
    brands: [],
    priceRange: "all",
    minRating: 0,
    inStockOnly: false,
    sameDayOnly: false,
    sortBy: "featured"
  };

  const searchInput = document.getElementById("header-search-input");
  if (searchInput) searchInput.value = "";
  const catSelect = document.getElementById("header-search-cat");
  if (catSelect) catSelect.value = "all";
  const inStockCb = document.getElementById("filter-in-stock");
  if (inStockCb) inStockCb.checked = false;
  const sameDayCb = document.getElementById("filter-same-day");
  if (sameDayCb) sameDayCb.checked = false;
  const sortSelect = document.getElementById("catalog-sort");
  if (sortSelect) sortSelect.value = "featured";

  const allPriceRadio = document.querySelector('input[name="price_range"][value="all"]');
  if (allPriceRadio) allPriceRadio.checked = true;

  document.querySelectorAll(".brand-filter-cb").forEach(cb => cb.checked = false);

  document.querySelectorAll(".cat-pill").forEach((pill, idx) => {
    if (idx === 0) {
      pill.classList.add("bg-slate-900", "text-white", "shadow-xs");
      pill.classList.remove("bg-slate-100", "text-slate-700");
    } else {
      pill.classList.remove("bg-slate-900", "text-white", "shadow-xs");
      pill.classList.add("bg-slate-100", "text-slate-700");
    }
  });

  applyCatalogFilters();
}

var lightningTimerInterval = null;
function initLightningCountdown() {
  if (lightningTimerInterval) clearInterval(lightningTimerInterval);
  
  let targetTime = parseInt(sessionStorage.getItem("pcware_lightning_target") || "0");
  const now = Date.now();
  if (!targetTime || targetTime <= now) {
    targetTime = now + (4 * 3600 + 28 * 60 + 15) * 1000;
    sessionStorage.setItem("pcware_lightning_target", targetTime.toString());
  }

  function tick() {
    const el = document.getElementById("lightning-timer");
    if (!el) return;
    const diff = targetTime - Date.now();
    if (diff <= 0) {
      targetTime = Date.now() + 6 * 3600 * 1000;
      sessionStorage.setItem("pcware_lightning_target", targetTime.toString());
    }
    const totalSecs = Math.max(0, Math.floor((targetTime - Date.now()) / 1000));
    const h = String(Math.floor(totalSecs / 3600)).padStart(2, "0");
    const m = String(Math.floor((totalSecs % 3600) / 60)).padStart(2, "0");
    const s = String(totalSecs % 60).padStart(2, "0");
    el.textContent = `${h}h : ${m}m : ${s}s`;
  }

  tick();
  lightningTimerInterval = setInterval(tick, 1000);
}

