function toggleCartDrawer(open) {
  const drawer = document.getElementById("cart-drawer");
  if (drawer) {
    if (open) drawer.classList.remove("hidden");
    else drawer.classList.add("hidden");
  }
}

function openMobileNavDrawer() {
  const drawer = document.getElementById("mobile-nav-drawer");
  if (drawer) drawer.classList.remove("hidden");
}

function closeMobileNavDrawer() {
  const drawer = document.getElementById("mobile-nav-drawer");
  if (drawer) drawer.classList.add("hidden");
}

function openMobileFilterModal() {
  const modal = document.getElementById("modal-mobile-filter");
  if (modal) modal.classList.remove("hidden");
}

function closeMobileFilterModal() {
  const modal = document.getElementById("modal-mobile-filter");
  if (modal) modal.classList.add("hidden");
}

function addToCart(productId) {
  const product = state.products.find(p => p.id === productId);
  if (!product) return;

  const existing = state.cart.find(item => item.id === productId);
  if (existing) {
    if (existing.qty < product.stock_quantity) {
      existing.qty += 1;
      showToast(product.name + " નો જથ્થો વધાર્યો (+1)");
    } else {
      showToast("માફ કરશો, ઉપલબ્ધ સ્ટોક માત્ર " + product.stock_quantity + " છે.", "error");
      return;
    }
  } else {
    state.cart.push({
      id: product.id,
      sku: product.sku,
      name: product.name,
      price: product.selling_price,
      image_url: product.image_url,
      category: product.category,
      qty: 1
    });
    showToast("કાર્ટમાં ઉમેર્યું: " + product.name);
  }

  saveCart();
  updateCartUI();
}

function updateCartQty(productId, delta) {
  const item = state.cart.find(i => i.id === productId);
  if (!item) return;

  item.qty += delta;
  if (item.qty <= 0) {
    state.cart = state.cart.filter(i => i.id !== productId);
  }
  saveCart();
  updateCartUI();
}

function saveCart() {
  localStorage.setItem("pcware_cart", JSON.stringify(state.cart));
}

function updateCartUI() {
  const badge = document.getElementById("cart-badge");
  const totalCount = state.cart.reduce((sum, i) => sum + i.qty, 0);
  if (badge) badge.textContent = totalCount;

  // Sync Mobile Header and Mobile Bottom Bar Cart Badges
  const mobBadge = document.getElementById("cart-badge-mob");
  if (mobBadge) mobBadge.textContent = totalCount;
  const mobBarBadge = document.getElementById("mob-bar-cart-badge");
  if (mobBarBadge) mobBarBadge.textContent = totalCount;

  const container = document.getElementById("cart-items-container");
  const subtotalEl = document.getElementById("cart-subtotal");
  const grandTotalEl = document.getElementById("cart-grand-total");
  const rowRefDisc = document.getElementById("cart-row-referral-disc");
  const valRefDisc = document.getElementById("cart-referral-disc-val");
  const rowPtsDisc = document.getElementById("cart-row-points-disc");
  const valPtsDisc = document.getElementById("cart-points-disc-val");
  const ptsBadge = document.getElementById("cart-available-pts-badge");

  const subtotal = state.cart.reduce((sum, i) => sum + (i.price * i.qty), 0);
  const refDiscount = state.appliedReferral ? Number(state.appliedReferral.discount_amount || 0) : 0;
  
  const availPoints = Number(state.customerRewardBalance || 0);
  if (ptsBadge) ptsBadge.textContent = `${availPoints} Pts`;

  let maxPointsDiscount = 0;
  if (state.redeemPoints && availPoints > 0) {
    const afterRef = Math.max(0, subtotal - refDiscount);
    maxPointsDiscount = Math.min(availPoints, afterRef);
  }

  const netPayable = Math.max(0, subtotal - refDiscount - maxPointsDiscount);

  if (subtotalEl) subtotalEl.textContent = "₹" + subtotal.toLocaleString('en-IN');
  if (grandTotalEl) grandTotalEl.textContent = "₹" + netPayable.toLocaleString('en-IN');

  if (rowRefDisc && valRefDisc) {
    if (refDiscount > 0) {
      rowRefDisc.classList.remove("hidden");
      valRefDisc.textContent = `-₹${refDiscount.toLocaleString('en-IN')}`;
    } else {
      rowRefDisc.classList.add("hidden");
    }
  }

  if (rowPtsDisc && valPtsDisc) {
    if (maxPointsDiscount > 0) {
      rowPtsDisc.classList.remove("hidden");
      valPtsDisc.textContent = `-₹${maxPointsDiscount.toLocaleString('en-IN')}`;
    } else {
      rowPtsDisc.classList.add("hidden");
    }
  }

  if (!container) return;

  if (state.cart.length === 0) {
    container.innerHTML = `
      <div class="text-center py-12 text-slate-400">
        <p class="font-medium">${t('cart_empty') || 'તમારું કાર્ટ ખાલી છે'}</p>
        <p class="text-xs">${t('cart_empty_sub') || 'પ્રોડક્ટ્સ ઉમેરો'}</p>
      </div>
    `;
    return;
  }

  container.innerHTML = state.cart.map(item => `
    <div class="py-3 flex items-center justify-between gap-3">
      <div class="flex items-center gap-3">
        <img src="${item.image_url || 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?w=400'}" class="w-12 h-12 object-contain bg-slate-100 rounded-lg p-1">
        <div>
          <h4 class="font-semibold text-xs text-slate-900 line-clamp-1">${item.name}</h4>
          <span class="text-xs text-brand-600 font-bold">₹${item.price.toLocaleString('en-IN')}</span>
        </div>
      </div>
      <div class="flex items-center gap-2">
        <button type="button" onclick="updateCartQty(${item.id}, -1)" class="w-6 h-6 rounded bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs flex items-center justify-center cursor-pointer">-</button>
        <span class="text-xs font-bold text-slate-800">${item.qty}</span>
        <button type="button" onclick="updateCartQty(${item.id}, 1)" class="w-6 h-6 rounded bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs flex items-center justify-center cursor-pointer">+</button>
      </div>
    </div>
  `).join("");
}

async function placeOrder() {
  if (state.cart.length === 0) {
    showToast("કાર્ટ ખાલી છે!", "error");
    return;
  }

  const name = document.getElementById("order-name")?.value.trim();
  const phone = document.getElementById("order-phone")?.value.trim();
  const address = document.getElementById("order-address")?.value.trim();
  const paymentMethod = document.getElementById("order-payment")?.value;

  if (!name || !phone || !address) {
    showToast("કૃપા કરીને નામ, મોબાઇલ અને સરનામું ભરો.", "error");
    return;
  }

  const subtotal = state.cart.reduce((sum, i) => sum + (i.price * i.qty), 0);
  const refDiscount = state.appliedReferral ? Number(state.appliedReferral.discount_amount || 0) : 0;
  const availPoints = Number(state.customerRewardBalance || 0);
  const pointsRedeemed = state.redeemPoints ? Math.min(availPoints, Math.max(0, subtotal - refDiscount)) : 0;
  const netPayable = Math.max(0, subtotal - refDiscount - pointsRedeemed);

  const payload = {
    customer_name: name,
    customer_phone: phone,
    customer_address: address,
    payment_method: paymentMethod,
    total_amount: netPayable,
    referral_code: state.appliedReferral ? state.appliedReferral.code : null,
    referral_discount: refDiscount,
    points_redeemed: pointsRedeemed,
    items: state.cart
  };

  const res = await apiPost("orders", payload);
  if (res && res.success) {
    showToast(`ઓર્ડર સફળ થયો! નેટ બિલિંગ: ₹${netPayable.toLocaleString('en-IN')} (ઓર્ડર નં: ${res.order_number})`, "success");
    state.cart = [];
    state.appliedReferral = null;
    state.redeemPoints = false;
    const cb = document.getElementById("cart-redeem-points-cb");
    if (cb) cb.checked = false;
    removeCartReferral();
    saveCart();
    updateCartUI();
    toggleCartDrawer(false);
    loadProducts();
    if (phone) loadCustomerRewards(phone);
    loadAdminReferrals();
  } else {
    showToast((res && res.error) || "ઓર્ડર પ્લેસ કરવામાં ક્ષતિ સર્જાઈ.", "error");
  }
}

