async function deleteProduct(id) {
  if (!confirm("શું તમે ખરેખર આ પ્રોડક્ટ ડિલીટ કરવા માંગો છો?")) return;
  const db = getLocalDB();
  db.products = db.products.filter(p => p.id !== id);
  saveLocalDB(db);
  showToast("પ્રોડક્ટ સફળતાપૂર્વક ડિલીટ કર્યો.");
  loadInventoryTable();
  loadProducts();
}

