async function handleCustomerTicketSubmit(e) {
  if (e) e.preventDefault();
  const sel = document.getElementById("cust-ticket-device-select");
  const cat = document.getElementById("cust-ticket-category");
  const desc = document.getElementById("cust-ticket-desc");

  const serial = sel ? sel.value : "";
  const devText = sel ? sel.options[sel.selectedIndex].text : "Laptop";
  const problemDesc = desc ? desc.value.trim() : "";
  if (!problemDesc) {
    alert("કૃપા કરીને સમસ્યાની વિગત દાખલ કરો.");
    return;
  }

  const custName = document.getElementById("cust-profile-name").textContent;
  const custPhone = document.getElementById("cust-profile-phone").textContent;

  const payload = {
    customer_name: custName,
    customer_phone: custPhone,
    device_model: devText,
    device_serial: serial,
    problem_category: cat ? cat.value : "Hardware Issue",
    reported_problem: problemDesc
  };

  try {
    const res = await apiPost("customer/tickets", payload);
    if (res && res.success) {
      alert("✅ સફળ! તમારી સર્વિસ ટિકિટ નોંધાઈ ગઈ છે: " + (res.ticket_number || "JS-2026-XXXX") + "\nPCWARE સર્વિસ લેબ ટીમ ટૂંક સમયમાં સંપર્ક કરશે.");
      toggleNewTicketForm(false);
      if (desc) desc.value = "";
      // Refresh dashboard
      loadCustomerDashboard(custPhone);
    }
  } catch (err) {
    console.error("Ticket submission failed:", err);
  }
}

